trait UserProfileMiddleNameAttributeHolder
{
    protected UserProfileMiddleNameVO|string|null $middleName = null;
    protected bool $middleNameAssigned = false;

    public function getMiddleNameOrCurrent(?UserProfileMiddleNameVO $middleName): ?UserProfileMiddleNameVO
    {
        return $this->middleNameAssigned ? ($this->middleName === null ? null : UserProfileMiddleNameVO::from($this->middleName)) : $middleName;
    }
    public function middleNameTryBuildInitial(ConstraintFailList $error): ?UserProfileMiddleNameVO
    {
        return  UserProfileMiddleNameVO::tryFrom($this->middleNameAssigned ? $this->middleName : null, $error);
    }
    public function middleName(UserProfileMiddleNameVO|string|null $middleName): static
    {
        $this->middleName = $middleName;
        $this->middleNameAssigned = true;
        return $this;
    }
    public function getMiddleName(): ?string
    {
        return $this->middleName instanceof UserProfileMiddleNameVO ? $this->middleName->value() : $this->middleName;
    }
    public function isMiddleNameAssigned(): bool
    {
        return $this->middleNameAssigned;
    }
    public function writeMiddleNameTo(mixed $att): void
    {
        if ($this->middleNameAssigned) {
            $att->middleName($this->middleName);
        }
    }
    public function readMiddleNameFrom(mixed $att): void
    {
        if ($att->isMiddleNameAssigned()) {
            $middleName = $att->getMiddleName();
            $this->middleName($middleName);
        }
    }
    public function unsetMiddleName(): static
    {
        $this->middleNameAssigned = false;
        return $this;
    }
    protected function withDefaultMiddleName(): void
    {
    }
    protected function withAssertedMiddleNameRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->middleNameAssigned = $this->middleNameAssigned) {
            $value->middleName = UserProfileMiddleNameVO::tryFrom($this->middleName, $errorsList);
        }
    }
}
